#!/usr/bin/env python3
"""dock/af3_complex_predict — auto-generated run.py (archetype=docking).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "docking"
BRAIN = "dock"
SKILL = "af3_complex_predict"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'af3_complex_predict', 'model_used': 'boltz-1', 'model_version': '0.4.1', 'n_seeds_run': 5, 'predictions': [{'seed': 0, 'pose_cif_path': '/runs/{tid}/af3_complex_predict/seed0_model.cif', 'ligand_pose_sdf_path': '...', 'plddt_ligand': 78.4, 'iptm_ligand': 0.83, 'pae_interface_max': 4.2, 'chain_pair_iptm_ligand': 0.71}], 'consensus_seed_index': 2, 'posebusters_check': {'overall_pass_rate': 0.85, 'per_pose': [{'pose_path': '...', 'all_pass': True, 'checks': {}}]}, 'confidence_assessment': {'iptm_high_means_pose_quality': True, 'iptm_does_NOT_mean_KD': '★ explicit declaration', 'n_seeds_agree_top1_rmsd_lt_2A': 4}, 'passed_sanity': True, 'provenance': {'command': '...', 'runtime_sec': 1842.3, 'remote_executed': True}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """复合预测:host praxis-dock env 自带 boltz(Boltz-1/2,AF3 替代);
    输入支持 YAML(boltz 标准)或 FASTA。

    输入:input_path (yaml 或 fasta) / output_dir / use_msa_server (bool,默认 True) /
          recycling_steps / diffusion_samples
    输出:n_chains / plddt_mean / ptm / iptm / pae_path / model_path / runtime_sec
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401

    input_path = payload.get("input_path") or payload.get("fasta") or payload.get("yaml")
    use_msa = bool(payload.get("use_msa_server", True))
    recycling = int(payload.get("recycling_steps", 3))
    diffusion_samples = int(payload.get("diffusion_samples", 1))
    out_dir = payload.get("output_dir") or _tempfile.mkdtemp(prefix="boltz_")

    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "predictor": "boltz", "use_msa_server": use_msa, "out_dir": out_dir}

    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL,
                "sequence": "", "model_path": "", "plddt_mean": 0.0, "ptm": 0.0,
                "n_residues": 0, "runtime_sec": 0.0,
                "diagnostics": {**diagnostics, "dry": True}}

    if not input_path or not _os.path.isfile(input_path):
        return {"ok": False, "error": f"input_path 不存在: {input_path!r}", "diagnostics": diagnostics}

    cmd = ["boltz", "predict", input_path, "--out_dir", out_dir,
           "--recycling_steps", str(recycling),
           "--diffusion_samples", str(diffusion_samples),
           "--output_format", "pdb"]
    if use_msa:
        cmd.append("--use_msa_server")

    t0 = _time.time()
    r = run_tool(cmd, timeout=int(payload.get("timeout_s", 3600)))
    diagnostics["subprocess"] = {"cmd": r.get("cmd")[:200], "wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "boltz predict 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}

    # 解析 out_dir 找 PDB + confidence_*.json
    parse_script = (
        "import json, os, sys, glob\n"
        f"out_dir = {out_dir!r}\n"
        "pdbs = sorted(glob.glob(os.path.join(out_dir, '**', '*.pdb'), recursive=True))\n"
        "conf = sorted(glob.glob(os.path.join(out_dir, '**', 'confidence_*.json'), recursive=True))\n"
        "ret = {'pdbs': pdbs, 'confidence_files': conf}\n"
        "if conf:\n"
        "    try:\n"
        "        c = json.load(open(conf[0]))\n"
        "        ret['plddt_mean'] = c.get('plddt_mean') or c.get('confidence_score')\n"
        "        ret['ptm'] = c.get('ptm_score') or c.get('ptm')\n"
        "        ret['iptm'] = c.get('iptm_score') or c.get('iptm')\n"
        "    except Exception as e:\n"
        "        ret['parse_err'] = repr(e)\n"
        "json.dump(ret, sys.stdout)\n"
    )
    rp = run_tool(["python3", "-c", parse_script], timeout=20)
    parsed = {}
    if rp["ok"]:
        try:
            parsed = json.loads(rp["stdout"])
        except json.JSONDecodeError:
            pass

    model_path = (parsed.get("pdbs") or [""])[0]
    return {"ok": True, "skill_id": SKILL,
            "sequence": "", "model_path": model_path,
            "plddt_mean": float(parsed.get("plddt_mean") or 0.0),
            "ptm": float(parsed.get("ptm") or 0.0),
            "iptm": float(parsed.get("iptm") or 0.0),
            "n_residues": 0,
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": {**diagnostics, "outputs": parsed}}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
